import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { BalanceResponse } from '~/entities/user/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const getBalance = () => {
  return resultify(axios.post<BalanceResponse>(API_URLS.balance));
};

export const useBalanceMutation = (options?: MutationOptions<void, CBDCAxiosError, BalanceResponse>) => {
  const mutation = useMutation<BalanceResponse, CBDCAxiosError, void>({
    ...options,
    mutationFn: () => getBalance(),
  });

  return {
    ...mutation,
  };
};
