import { useEffect, useState } from 'react';
import { useMyBankAccountPage } from '~/pages/account/my-bank-account/use-my-bank-account-page';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useBalanceMutation } from '~/entities/user/api/use-balance-mutation';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetLinkedAccountListMutation } from '~/entities/user/api/use-get-linked-account-list-mutation';
import { LinkedAccountResponse } from '~/entities/user/model/types';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';

export const MyBankAccountPage = () => {
  useSetHeaderTitle(i18n.t('checkLinkedAccount'));
  const { data: userRes } = useGetUserInfoQuery();
  // IF-006 잔액조회 API 호출
  const { mutateAsync: getBalance } = useBalanceMutation();
  const { mutateAsync: linkedAccountListRes } = useGetLinkedAccountListMutation();
  const { shortBankName } = useComBankInfo(appConfig.BANK_CODE ?? '');
  const { myBankAccountConfirm } = useMyBankAccountPage();
  const [acnutBalance, setAcnutBalance] = useState<number>(0);
  const [linkedAccountList, setLinkedAccountList] = useState<LinkedAccountResponse[]>([]);

  useEffect(() => {
    getBalance().then((response) => {
      setAcnutBalance(response?.acnutBalance ?? 0);
    });

    linkedAccountListRes().then((response) => {
      setLinkedAccountList(response);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="content sub">
      {linkedAccountList.length > 0 &&
        linkedAccountList.map((account, index) => (
          <div key={index} className="my-wallet-info-wrapper">
            <div className="acnt-info">
              <p className="info">{i18n.t('linkedAccount')}</p>
              <span className="balance-info">
                {shortBankName} {account.acnutno}
              </span>
            </div>
            {/* <button type="button" className="chk-btn" onClick={() => myBankAccountConfirm()}>
                    {i18n.t('accountChangeText')}
                  </button> */}
            <div className="acnt-info">
              <p className="info">{i18n.t('accountBalance')}</p>
              <span className="balance-info">
                {account.acnutnoBlce?.toLocaleString()} {i18n.t('won')}
              </span>
            </div>
          </div>
        ))}
      <div className="line-box line-10">
        <dl className="info-list">
          <dt>{i18n.t('linkedAccountInfo')}</dt>
          <dd>{i18n.t('text:linkedAccountCannotBeChanged')}</dd>
          <dd>{i18n.t('text:linkedAccountDepositAndConversion')}</dd>
        </dl>
      </div>
    </div>
  );
};
