import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { VerificationType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const useMyBankAccountPage = () => {
  const { navigate } = useNavigate();
  const { openPinBottomSheet } = usePinBottomSheet();
  const { data: userRes } = useGetUserInfoQuery();
  const handleClick = () => {
    openPinBottomSheet((close) => {
      close();
      setTimeout(() => {
        navigate(PATHS.account.verifyBank, {
          replace: true,
          state: {
            ...userRes.tbCstmrMastr,
            verificationType: VerificationType.ReSetUser,
          },
        });
      }, 0);
    });
  };
  const myBankAccountConfirm = () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={<span className="whitespace-pre-line break-words">{i18n.t('accountChangeConfirm')}</span>}
          buttonLabel={[i18n.t('cancel'), i18n.t('changeConfirm')]}
          onCancelClick={close}
          onConfirmClick={() => {
            close();
            handleClick();
          }}
        />
      );
    });
  };

  return { myBankAccountConfirm };
};
