import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { LinkedAccountResponse } from '~/entities/user/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const getLinkedAccountList = () => {
  return resultify(axios.get<LinkedAccountResponse[]>(API_URLS.linkedAcnutList));
};

export const useGetLinkedAccountListMutation = (
  options?: MutationOptions<void, CBDCAxiosError, LinkedAccountResponse[]>,
) => {
  const mutation = useMutation<LinkedAccountResponse[], CBDCAxiosError, void>({
    ...options,
    mutationFn: () => getLinkedAccountList(),
  });

  return {
    ...mutation,
  };
};
